public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int N = sc.nextInt();
    int A = sc.nextInt();
    int[] T = new int[N];
    int ansT = 0;

    for (int i = 0; i < N; i++) {
        T[i] = sc.nextInt();
    }

    for (int i = 0; i < N; i++) {
        if (ansT >= T[i]) {
            ansT = ansT + A;
        } else {
            ansT = T[i] + A;
        }
        System.out.println(ansT);
    }
}
